int max_int(int a, int b) {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

float max_float(float a, float b) {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

test_setup_files.test_max_main.c:
#include <assert.h>
#include <stdio.h>

int max_int(int a, int b);
float max_float(float a, float b);

int main(void) {
    assert(max_int(3, 5) == 5);
    assert(max_int(5, 3) == 5);
    assert(max_int(-1, -5) == -1);
    assert(max_int(7, 7) == 7);
    assert(max_float(1.5f, 2.5f) == 2.5f);
    assert(max_float(2.5f, 1.5f) == 2.5f);
    assert(max_float(-2.5f, -9.5f) == -2.5f);
    printf("PASS\n");
    return 0;
}
